window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-31cbb8a507d7f3fd"]={"versions": [{"id": "FIG-31cbb8a507d7f3fd", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Diagramm definiert die Modellierung von Timing-Ereignissen im Kontext von Moduswechseln (<code>TDEventModeDeclaration</code>) auf der Ebene des virtuellen Funktionsbusses (VFB) bzw. der Schnittstellenkommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TDEventVfb</code>: Abstrakte Basisklasse, spezialisiert aus <code>TimingDescriptionEvent</code>.</li>\n<li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code> mit dem Attribut <code>isExternal: Boolean</code>. Besitzt eine gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> auf ein <code>PortPrototype</code> (stereotypisiert mit <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).</li>\n<li><code>TDEventModeDeclaration</code>: Konkrete Spezialisierung von <code>TDEventVfbPort</code>. Enthält das Attribut <code>+ tdEventModeDeclarationType: TDEventModeDeclarationTypeEnum</code>. Besitzt eine gerichtete Assoziation <code>+modeDeclaration</code> mit fester Kardinalität <code>1</code> auf ein <code>ModeDeclarationGroupPrototype</code> (stereotypisiert mit <code>«AtpPrototype»</code>).</li>\n<li><code>«enumeration» TDEventModeDeclarationTypeEnum</code>: Enumerationstyp mit den Werten:</li>\n<li><code>modeDeclarationSwitchInitiated</code></li>\n<li><code>modeDeclarationSwitchCompleted</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Strukturmodell ab. Zur Laufzeit referenziert ein <code>TDEventModeDeclaration</code> einen konkreten Modusübergang eines <code>ModeDeclarationGroupPrototype</code> an einem optionalen <code>PortPrototype</code>. Das Attribut <code>tdEventModeDeclarationType</code> bestimmt, ob das Timing-Ereignis bei der Initiierung (<code>modeDeclarationSwitchInitiated</code>) oder beim Abschluss (<code>modeDeclarationSwitchCompleted</code>) des Moduswechsels erfasst wird. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Port-Grenze nach außen hin auftritt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Timing-Analyse ist die präzise Zuordnung des Ereignistyps via <code>TDEventModeDeclarationTypeEnum</code> maßgeblich, um Latenzketten zwischen dem Start und der Vollendung eines Moduswechsels normativ zu definieren. Die Multiplizität von genau 1 bei <code>+modeDeclaration</code> verlangt eine zwingende Referenzierung eines <code>ModeDeclarationGroupPrototype</code>, während die Zuordnung zu einem <code>PortPrototype</code> (<code>0..1</code>) optional ist.</p>"}, {"id": "FIG-4a75dfcc51583fc6", "releases": ["R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Klassendiagramm zur Spezifikation des Metamodells der AUTOSAR Timing Extensions (TPS Adaptive Platform Timing Extensions). Das Diagramm definiert die Modellierung von Timing-Ereignissen im Kontext von Moduswechseln (<code>TDEventModeDeclaration</code>) auf der Ebene des virtuellen Funktionsbusses (VFB) bzw. der Schnittstellenkommunikation.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\">\n<li><code>TDEventVfb</code>: Abstrakte Basisklasse, spezialisiert aus <code>TimingDescriptionEvent</code>.</li>\n<li><code>TDEventVfbPort</code>: Abstrakte Spezialisierung von <code>TDEventVfb</code> mit dem Attribut <code>isExternal: Boolean</code>. Besitzt eine gerichtete Assoziation <code>+port</code> mit Kardinalität <code>0..1</code> auf ein <code>PortPrototype</code> (stereotypisiert mit <code>«AtpBlueprintable»</code>, <code>«AtpPrototype»</code>).</li>\n<li><code>TDEventModeDeclaration</code>: Konkrete Spezialisierung von <code>TDEventVfbPort</code>. Enthält das Attribut <code>+ tdEventModeDeclarationType: TDEventModeDeclarationTypeEnum</code>. Besitzt eine gerichtete Assoziation <code>+modeDeclaration</code> mit fester Kardinalität <code>1</code> auf ein <code>ModeDeclarationGroupPrototype</code> (stereotypisiert mit <code>«AtpPrototype»</code>).</li>\n<li><code>«enumeration» TDEventModeDeclarationTypeEnum</code>: Enumerationstyp mit den Werten:</li>\n<li><code>modeDeclarationSwitchInitiated</code></li>\n<li><code>modeDeclarationSwitchCompleted</code></li>\n</ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm bildet ein statisches Strukturmodell ab. Zur Laufzeit referenziert ein <code>TDEventModeDeclaration</code> einen konkreten Modusübergang eines <code>ModeDeclarationGroupPrototype</code> an einem optionalen <code>PortPrototype</code>. Das Attribut <code>tdEventModeDeclarationType</code> bestimmt, ob das Timing-Ereignis bei der Initiierung (<code>modeDeclarationSwitchInitiated</code>) oder beim Abschluss (<code>modeDeclarationSwitchCompleted</code>) des Moduswechsels erfasst wird. Das Attribut <code>isExternal</code> kennzeichnet, ob das Ereignis an der Port-Grenze nach außen hin auftritt.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Für die Timing-Analyse ist die präzise Zuordnung des Ereignistyps via <code>TDEventModeDeclarationTypeEnum</code> maßgeblich, um Latenzketten zwischen dem Start und der Vollendung eines Moduswechsels normativ zu definieren. Die Multiplizität von genau 1 bei <code>+modeDeclaration</code> verlangt eine zwingende Referenzierung eines <code>ModeDeclarationGroupPrototype</code>, während die Zuordnung zu einem <code>PortPrototype</code> (<code>0..1</code>) optional ist.</p>"}], "trans": [{"from": "FIG-31cbb8a507d7f3fd", "to": "FIG-4a75dfcc51583fc6", "fr": "R20-11", "tr": "R21-11", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\">\n<li><code>TDEventModeDeclarationTypeEnum</code>: Entfernung der Zwischenüberschrift <code>Attributes</code> sowie der vorangestellten Sichtbarkeitsmodifikatoren <code>+</code> vor den Enumerationswerten <code>modeDeclarationSwitchInitiated</code> und <code>modeDeclarationSwitchCompleted</code>.</li>\n</ul>"}]};
